/****************************************************************************
 * apps/examples/velatime/velatime_main.c
 *
 * VelaTime - AI Student Time Planner for openvela
 ****************************************************************************/

#include <nuttx/config.h>
#include <unistd.h>
#include <sys/boardctl.h>

#include <lvgl/lvgl.h>

#undef NEED_BOARDINIT

#if defined(CONFIG_BOARDCTL) && !defined(CONFIG_NSH_ARCHINIT)
#  define NEED_BOARDINIT 1
#endif

static void velatime_build_home_screen(lv_obj_t *parent)
{
  lv_obj_t *scr = lv_obj_create(NULL);
  lv_obj_set_style_bg_color(scr, lv_color_hex(0x10131A), 0);

  lv_obj_t *title = lv_label_create(scr);
  lv_label_set_text(title, "VelaTime");
  lv_obj_set_style_text_color(title, lv_color_hex(0xFFFFFF), 0);
  lv_obj_set_style_text_font(title, &lv_font_montserrat_20, 0);
  lv_obj_align(title, LV_ALIGN_TOP_LEFT, 16, 12);

  lv_obj_t *subtitle = lv_label_create(scr);
  lv_label_set_text(subtitle, "Now recommended:");
  lv_obj_set_style_text_color(subtitle, lv_color_hex(0x8890A0), 0);
  lv_obj_align_to(subtitle, title, LV_ALIGN_OUT_BOTTOM_LEFT, 0, 8);

  lv_obj_t *card = lv_obj_create(scr);
  lv_obj_set_size(card, 220, 140);
  lv_obj_set_style_bg_color(card, lv_color_hex(0x1C2130), 0);
  lv_obj_set_style_radius(card, 12, 0);
  lv_obj_set_style_border_width(card, 0, 0);
  lv_obj_align(card, LV_ALIGN_TOP_LEFT, 16, 84);

  lv_obj_t *card_title = lv_label_create(card);
  lv_label_set_text(card_title, "高数作业");
  lv_obj_set_style_text_color(card_title, lv_color_hex(0xFFFFFF), 0);
  lv_obj_align(card_title, LV_ALIGN_TOP_LEFT, 12, 10);

  lv_obj_t *card_meta = lv_label_create(card);
  lv_label_set_text(card_meta, "今天 18:00 截止  |  预计 30 分钟");
  lv_obj_set_style_text_color(card_meta, lv_color_hex(0x8890A0), 0);
  lv_obj_align_to(card_meta, card_title, LV_ALIGN_OUT_BOTTOM_LEFT, 0, 8);

  lv_obj_t *card_action = lv_label_create(card);
  lv_label_set_text(card_action, ">> 开始 [ 延后 ]");
  lv_obj_set_style_text_color(card_action, lv_color_hex(0xFF8A3D), 0);
  lv_obj_align_to(card_action, card_meta, LV_ALIGN_OUT_BOTTOM_LEFT, 0, 18);

  lv_scr_load(scr);
}

int main(int argc, FAR char *argv[])
{
  lv_nuttx_dsc_t info;
  lv_nuttx_result_t result;

  if (lv_is_initialized())
    {
      return -1;
    }

#ifdef NEED_BOARDINIT
  boardctl(BOARDIOC_INIT, 0);
#endif

  lv_init();

  lv_nuttx_dsc_init(&info);

#ifdef CONFIG_LV_USE_NUTTX_LCD
  info.fb_path = "/dev/lcd0";
#endif

#ifdef CONFIG_INPUT_TOUCHSCREEN
  info.input_path = "/dev/input0";
#endif

  lv_nuttx_init(&info, &result);

  if (result.disp == NULL)
    {
      return 1;
    }

  velatime_build_home_screen(result.disp ? lv_disp_get_scr_act(result.disp) : NULL);

  while (1)
    {
      uint32_t idle;
      idle = lv_timer_handler();
      idle = idle ? idle : 1;
      usleep(idle * 1000);
    }

  lv_nuttx_deinit(&result);
  lv_deinit();
  return 0;
}
EOF
```

> 注意：`velatime_build_home_screen(NULL)` 那行我做了兜底。LVGL 加载屏幕用 `lv_scr_load(scr)` 即可，不依赖传入的 parent。你执行后如有 `result.disp` 引用问题，我稍后修正。

