## 解析 "YYYY-MM-DD HH:MM" 的辅助函数

我用 `sscanf` 把字符串拆成 年/月/日/时/分：

```c
/* 把 "YYYY-MM-DD HH:MM" 解析成 time_t，失败返回 0 */
static time_t deadline_to_time(const char *s)
{
  struct tm tmv;
  int y, mo, d, h, mi;

  if (sscanf(s, "%d-%d-%d %d:%d", &y, &mo, &d, &h, &mi) != 5)
    {
      return 0;
    }

  memset(&tmv, 0, sizeof(tmv));
  tmv.tm_year = y - 1900;
  tmv.tm_mon  = mo - 1;
  tmv.tm_mday = d;
  tmv.tm_hour = h;
  tmv.tm_min  = mi;
  tmv.tm_isdst = -1;

  return mktime(&tmv);
}
```

## 修改 score 计算

```c
#include <time.h>

static int urgency_score(const char *deadline)
{
  time_t now, dl;
  long diff_minutes;

  /* 当前时间 */
  struct timespec ts;
  if (clock_gettime(CLOCK_REALTIME, &ts) != 0)
    {
      return 20;
    }
  now = ts.tv_sec;

  dl = deadline_to_time(deadline);
  if (dl == 0)
    {
      return 20;
    }

  diff_minutes = (long)(dl - now) / 60;

  if (diff_minutes <= 0)
    {
      return 100;  /* 已截止或即将截止，最紧急 */
    }
  else if (diff_minutes <= 24 * 60)
    {
      return 80;   /* 24 小时内 */
    }
  else if (diff_minutes <= 72 * 60)
    {
      return 50;   /* 3 天内 */
    }
  return 20;       /* 更晚 */
}
```

然后把 `core_recommend_pick` 里的 `urgency = 100` 改成 `urgency = urgency_score(t->deadline)`。

