```bash
cat > /home/yy/openvela-contest/contest2026_481_naiwajundui/app/velatime/core/core_agent_sync.c << 'EOF'
#include "core_agent_sync.h"
#include "core_task.h"
#include "../include/velatime_types.h"

#include <stdio.h>
#include <string.h>

#define AGENT_TASKS_FILE "/data/ai_agent/TASKS.md"

int core_agent_sync_from_file(void)
{
  FILE *fp;
  char line[256];
  int imported = 0;

  fp = fopen(AGENT_TASKS_FILE, "r");
  if (!fp)
    {
      return -1;
    }

  while (fgets(line, sizeof(line), fp) != NULL)
    {
      velatime_task_t t;
      char title[128];
      char date[32];
      char time_str[16];

      memset(&t, 0, sizeof(t));

      /* 解析形如 "- [ ] [2026-09-07] 明天下午交高数作业（预计耗时半小时）" 的行 */
      if (sscanf(line, "- [ ] [%15[^]]] %127[^（(]", date, title) != 2)
        {
          continue;
        }

      /* 截止时间默认当天 18:00 */
      snprintf(t.deadline, VELATIME_MAX_DEADLINE, "%s 18:00", date);

      strncpy(t.title, title, VELATIME_MAX_TITLE - 1);
      t.title[VELATIME_MAX_TITLE - 1] = '\0';

      t.estimated_minutes = 30;
      strncpy(t.priority, "medium", VELATIME_MAX_PRIORITY - 1);
      t.priority[VELATIME_MAX_PRIORITY - 1] = '\0';
      t.status = VELATIME_STATUS_WAITING;

      if (core_task_add(&t) != NULL)
        {
          imported++;
        }
    }

  fclose(fp);
  return imported;
}
