         STUDENT_TASK_SKILL_FILE);
  return 0;
}

int core_agent_sync_from_file(void)
{
  FILE *fp;
  char line[256];
  int imported = 0;

  fp = fopen(AGENT_TASKS_FILE, "r");
  if (!fp)
    {
      printf("VelaTime: cannot open %s\n", AGENT_TASKS_FILE);
      return -1;
    }

  while (fgets(line, sizeof(line), fp) != NULL)
    {
      velatime_task_t t;
      char title[128];
      char date[32];

      memset(&t, 0, sizeof(t));

      /* 解析 "- [ ] [2026-09-07] 明天下午交高数作业" 这种行 */
      if (sscanf(line, "- [ ] [%15[^]]] %127[^（(]", date, title) != 2)
        {
          continue;
        }

      strncpy(t.deadline, date, VELATIME_MAX_DEADLINE - 1);
      t.deadline[VELATIME_MAX_DEADLINE - 1] = '\0';

      strncpy(t.title, title, VELATIME_MAX_TITLE - 1);
      t.title[VELATIME_MAX_TITLE - 1] = '\0';

      t.estimated_minutes = 30;
      strncpy(t.priority, "medium", VELATIME_MAX_PRIORITY - 1);
      t.priority[VELATIME_MAX_PRIORITY - 1] = '\0';
      t.status = VELATIME_STATUS_WAITING;

      if (core_task_add(&t) != NULL)
        {
          imported++;
        }
    }

  fclose(fp);

  printf("VelaTime: parsed %d task(s) from %s\n",
         imported, AGENT_TASKS_FILE);

  return imported;
}

