/* 将 VelaTime 的学生任务规划 skill 安装到 AI Agent 数据目录。
   成功或文件已存在返回 0，失败返回 -1。 */
int core_agent_skill_install(void);

/* 从 Agent 的任务文件读取任务并导入 core_task。
   成功导入返回导入的任务数量，失败返回 -1。 */
